import{_ as e}from"./chunks/image3.B8UTGdq_.js";import{_ as s,o as a,c as i,ah as o}from"./chunks/framework.inWAIpeo.js";const n="/projects/PuppyPi/en/latest/assets/image5.a5w3ZVTV.png",p="/projects/PuppyPi/en/latest/assets/image6.CftKazMD.png",r="/projects/PuppyPi/en/latest/assets/image8.CbXEHiL5.png",h="/projects/PuppyPi/en/latest/assets/image13.BEF4nRN7.png",l="/projects/PuppyPi/en/latest/assets/image15.CgNwoJNn.png",d="/projects/PuppyPi/en/latest/assets/image16.DEe1LP7U.jpeg",F=JSON.parse('{"title":"18. ROS1-ROS Robot Group Sending Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/18.ROS1_ROS_Robot_Group_Sending_Control.md","filePath":"docs/18.ROS1_ROS_Robot_Group_Sending_Control.md"}'),c={name:"docs/18.ROS1_ROS_Robot_Group_Sending_Control.md"};function g(u,t,m,k,b,v){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="_18-ros1-ros-robot-group-sending-control" tabindex="-1">18. ROS1-ROS Robot Group Sending Control <a class="header-anchor" href="#_18-ros1-ros-robot-group-sending-control" aria-label="Permalink to &quot;18. ROS1-ROS Robot Group Sending Control&quot;">​</a></h1><h2 id="_18-1-master-and-slave-machine-configuration" tabindex="-1">18.1 Master and Slave Machine Configuration <a class="header-anchor" href="#_18-1-master-and-slave-machine-configuration" aria-label="Permalink to &quot;18.1 Master and Slave Machine Configuration&quot;">​</a></h2><h3 id="_18-1-1-getting-ready" tabindex="-1">18.1.1 Getting Ready <a class="header-anchor" href="#_18-1-1-getting-ready" aria-label="Permalink to &quot;18.1.1 Getting Ready&quot;">​</a></h3><p>(1) Please prepare at least 2 or more PuppyPi. Two PuppyPi are used in this lesson for demonstration.</p><p>(2) Set development environment. Please download and install VNC according to &quot;<a href="./3.Remote_Tool_Installation_Connection.html"><strong>3. Remote Tool Installation and Docker Entry Method</strong></a>&quot;.</p><h3 id="_18-1-2-working-principle" tabindex="-1">18.1.2 Working Principle <a class="header-anchor" href="#_18-1-2-working-principle" aria-label="Permalink to &quot;18.1.2 Working Principle&quot;">​</a></h3><p>By configuring the master and the slave machine in the same network, the master sends motion commands to the slave via a multicast program, achieving the effect of controlling the slave.</p><p id="anchor_18_1_3"></p><h3 id="_18-1-3-operation-steps" tabindex="-1">18.1.3 Operation Steps <a class="header-anchor" href="#_18-1-3-operation-steps" aria-label="Permalink to &quot;18.1.3 Operation Steps&quot;">​</a></h3><ul><li><strong>Network Configuration</strong></li></ul><p>(1) Configure Master Network</p><p>① Firstly, select one PuppyPi as the master, power it on, and then remotely connect to its system desktop.</p><p>② Then open the command line terminal to go to the directory. Input command and press Enter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox</span></span></code></pre></div><p>③ Use vim editor to open Wi-Fi. Configure file and input command. Then press Enter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>④ After modification, press Esc to exit editing mode. Then input <strong>&quot;:wq&quot;</strong> to save and exit.</p><img loading="lazy" height="423" width="749" src="'+n+'" class="common_img"><p>⑤ After modification, press Esc to exit editing mode. Then input <strong>&quot;:wq&quot;</strong> to save and exit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><img loading="lazy" height="423" width="748" src="'+p+'" class="common_img"><p>⑥ Input the command to restart the master.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><p>⑦ After the master restarts, when reconnecting to the master&#39;s Wi-Fi, you will need to enter the Wi-Fi password &quot;<strong>hiwonder</strong>&quot;.</p><p>(2) Configure Slave Network</p><p>① Turn on the slave, and remote connect it to the system desktop.</p><p>② Open the command line terminal. Input the command and press Enter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox</span></span></code></pre></div><p>③ Use vim editor to open wifi. Configure the file and input command. Then press Enter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>④ Press <strong>&quot;i&quot;</strong> to go to the editing mode. Change the two lines of code for the WI-FI name and password as shown in the figure below. Find the four lines of code highlighted in the box.</p><img loading="lazy" height="424" width="748" src="'+r+'" class="common_img"><p>Setting the network mode of the slave device to &#39;2&#39; will be in LAN mode, while &#39;HW-123&#39; and &#39;hiwonder&#39;.</p><p>⑤ After modification, press Esc once to exit the editing mode. Then type <strong>&quot;:wq&quot;</strong> and press Enter to save and exit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><p>⑥ Input command <strong>&quot;sudo reboot&quot;</strong> to restart the device. Do not skip this step!</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><h2 id="_18-2-group-sending-control-startup-method" tabindex="-1">18.2 Group Sending Control Startup Method <a class="header-anchor" href="#_18-2-group-sending-control-startup-method" aria-label="Permalink to &quot;18.2 Group Sending Control Startup Method&quot;">​</a></h2><h3 id="_18-2-1-enable-group-sending-control" tabindex="-1">18.2.1 Enable Group Sending Control <a class="header-anchor" href="#_18-2-1-enable-group-sending-control" aria-label="Permalink to &quot;18.2.1 Enable Group Sending Control&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Commands must be entered with strict attention to capitalization and spaces.</p></section><p>(1) Select a PuppyPi robot dog as the host and start it, then connect to the Raspberry Pi desktop remotely via VNC.</p><p>(2) Click <img loading="lazy" height="74" width="81" src="'+e+'" style="width:70px;"> on the upper left corner to open the Terminator terminal.</p><p>(3) Input the command and press Enter to close auto-start program.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.stop_ros.sh</span></span></code></pre></div><p>(4) Input the command to configure master the host&#39;s environment variable.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi_master_env.sh</span></span></code></pre></div><p>(5) Return to the terminal interface of the slave device, enter the command to disable the automatic startup feature, and press Enter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.stop_ros.sh</span></span></code></pre></div><p>(6) In the terminal interface of the slave device, enter the command to start the slave group control program.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_control</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puppy_mul.py</span></span></code></pre></div><p>(7) Then open a new terminal, type &#39;ssh 192.168.149.119&#39; and press Enter, enter the password &#39;raspberrypi&#39;, and type &#39;source multi_slave_env.sh 192.168.149.1&#39; to set up the environment variables for the slave (this is for starting the multi-slave control topic, and you can also set it up as host environment variables before proceeding with steps (8) to (11). The command is :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.149.119</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi_slave_env.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.149.1</span></span></code></pre></div><p>(8) Enter the command to view the topic information of the master/slave (if the topic information of the master/slave does not appear, it means that the corresponding multi-slave control program of the master/slave is not started, refer to the previous &#39;steps 1~6&#39; for reoperation).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rostopic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /multi_robot/runActionGroup</span></span></code></pre></div><p>(9) Enter &#39;rostopic pub /multi_robot/runActionGroup&#39;, then press the Tab key 3 times to complete the command as <code>rostopic pub /multi_robot/runActionGroup std_msgs/String &quot;data: &#39;&#39;&quot;</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rostopic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /multi_robot/runActionGroup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_msgs/String</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data: &#39;&#39;&quot;</span></span></code></pre></div><p>(10) Fill in the name of the action group in &quot;<strong>data: &#39;&#39;</strong>&quot; (The action group can be found in the directory &#39;/home/ubuntu/software/puppypi_control/ActionGroups&#39;).</p><img loading="lazy" height="283" width="823" src="'+h+'" class="common_img"><p>(11) Enter the command to excute the action group.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rosrun puppy_control puppy_mul.py</span></span></code></pre></div><p>(12) If you want to execute other actions, in the terminal where the multi-slave control topic is started, press &#39;Ctrl+C&#39; to close it, then press the arrow key on the keyboard, modify the action group name, and press Enter to execute.</p><img loading="lazy" height="269" width="824" src="'+l+'" class="common_img"><p>(13) If you need to close this gameplay, you can press <strong>&#39;Ctrl+C&#39;</strong> in the LX terminal interface. If closing fails, you can press it multiple times.</p><p>(14) Next, in the terminal interface of both the host and the slave, refer to <a href="#anchor_18_1_3">&quot;<strong>18.1.3 Operation Steps -&gt; Network Configuration</strong>&quot;</a> and add comments to the Wi-Fi configuration file. Restore it to direct connection mode.</p><h3 id="_18-2-2-program-outcome" tabindex="-1">18.2.2 Program Outcome <a class="header-anchor" href="#_18-2-2-program-outcome" aria-label="Permalink to &quot;18.2.2 Program Outcome&quot;">​</a></h3><p>Once the game is initiated, both the master and the slave will execute the same actions. After the action group is completed, you can also observe the printed action group names in the terminal interface of both the master and the slave running the multicast control program.</p><img loading="lazy" height="69" width="554" class="common_img" src="'+d+'">',68)])])}const _=s(c,[["render",g]]);export{F as __pageData,_ as default};
